custom_css:
/*
禁二传/商用
作者：再活五分钟
*/

@import url("https://fontsapi.zeoseven.com/882/main/result.css");

:root {
  --black30a: #FFFFFF;
  --black50a: #FFFFFF;
  --black70a: #E0E0E0;
}

:not([class*="fa-"]):not(.fas):not(.far):not(.fal):not(.fab):not(.fa),
#send_textarea,
.menu_button_icon.fa-repeat,
.menu_button_icon.fa-bolt {
  font-family: "Monu Hani";
}

.menu_button_icon.fa-repeat::before,
.menu_button_icon.fa-bolt::before {
  font-family: "Font Awesome 6 Free";
  font-weight: 900;
}

/* 隐藏滚动条 @lambkinling */
::-webkit-scrollbar { display: none; }

/* 文本两端对齐 @lambkinling */
.mes_text {
  text-align: justify;
}

/* 移除右侧边距 @inkfoxxxx */
.mes_block .ch_name,
.mes_block .mes_text {
  width: 100%;
  box-sizing: border-box;
  margin: 0;
  padding-left: 0;
  padding-right: 0;
}

.mes_block .mes_text {
  padding-top: calc(var(--mainFontSize) * 0.8);
  padding-bottom: 20px;
  text-shadow: none !important;
}

.drawer-content { border-radius: 0; }

/* 菜单栏全屏化 @_nak.a.ri */
.drawer-content.openDrawer {
  max-height: calc(100dvh - var(--topBarBlockSize));
  height: calc(100dvh - var(--topBarBlockSize));
}

#left-nav-panel,
#right-nav-panel {
  height: 100dvh;
  max-height: 100dvh;
}

@media (max-width: 600px) {
  #right-nav-panel {
    max-height: calc(100dvh - var(--topBarBlockSize));
  }
}

/* 移除全局阴影 @lambkinling */
body * {
  box-shadow: none !important;
  filter: none !important;
}

.drawer-content {
  background-image: url('https://files.catbox.moe/yxh5c4.jpg') !important; /* 图源 @小布偶 */
  /* 可在此处替换为自定义背景图，格式：background-image: url('图片链接') !important; */
  background-size: cover !important;
  background-position: center !important;
  background-repeat: no-repeat !important;
}

/* 修复提示词头部显示与末条消息间距 @blue_0310 */
.completion_prompt_manager_header { color: var(--SmartThemeBodyColor) !important; }

.mes.last_mes > *:not(.mes_block) { padding-bottom: 0; }

.completion_prompt_manager_list_separator { display: none !important; }

#chat .mes:last-child { margin-bottom: 20px !important; }

div:has(#aux_field) { margin-bottom: 5px !important; }

#settingsSearch {
  background-color: #FFFFFF !important;
  border: none !important;
  box-shadow: 0 1px 1px rgba(0, 0, 0, 0.1) !important;
}

.inline-drawer-icon::before { display: none; }

.flex-container.flexFlowRow:has(#settingsSearch) { position: relative; }

#settingsSearch::placeholder { color: transparent !important; }

/* 自定义占位文本 参考@inkfoxxxx */
.flex-container.flexFlowRow:has(#settingsSearch:placeholder-shown)::before {
  content: "解不开的心结就把它变成蝴蝶结⌯>ᴗo⌯ .ᐟ.ᐟ";
  color: #999;
  font-size: 10px;
  position: absolute;
  left: 70px;
  top: 50%;
  transform: translateY(-50%);
  pointer-events: none;
  z-index: 10;
}

hr {
  position: relative !important;
  border: none !important;
  height: 1px !important;
  background: transparent !important;
  margin: 14px 0 !important;
  overflow: visible !important;
}

hr::before {
  content: "─── ⁺ ₊ 𝙞 𝙡𝙤𝙫𝙚 𝙪𝙪˚⋆𝜗𝜚⋆───" !important;
  position: absolute !important;
  left: 50% !important;
  top: 50% !important;
  transform: translate(-50%, -50%) !important;
  background: var(--bg-100) !important;
  padding: 0 3px !important;
  color: #333 !important;
  font-size: 11px !important;
  white-space: nowrap !important;
  max-width: none !important;
}

#chat .mes {
  width: 94% !important;
  max-width: 100% !important;
  margin: 25px auto 85px !important;
  position: relative;
  background: #fff !important;
  -webkit-backdrop-filter: blur(10px) !important;
  border-radius: 1px !important;
  overflow: visible !important;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding-bottom: 15px !important;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.1), 0 2px 12px rgba(0, 0, 0, 0.02) !important;
}

.mes {
  display: flex !important;
  flex-direction: column !important;
  align-items: flex-start !important;
}

.mes[is_user="true"] { align-items: flex-end !important; }

.mes .mesAvatarWrapper {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 12px;
  padding: 0 10px;
  position: relative !important;
  z-index: 3 !important;
  margin-top: -85px !important;
  margin-bottom: 10px !important;
  flex-shrink: 0 !important;
  padding-bottom: 25px !important;
}

.mes[is_user="true"] .mesAvatarWrapper { flex-direction: row-reverse; }

.mes .mes_block {
  border-bottom: 1px solid rgba(0, 0, 0, 0.12) !important;
  position: relative !important;
  width: 100%;
  padding: 3em 6px 30px 6px !important;
}

#chat .mes .avatar {
  position: absolute !important;
  z-index: 3 !important;
  top: 55px !important;
  width: 40px !important;
  height: 40px !important;
}

#chat .mes[is_user="false"] .avatar { left: 0px !important; }
#chat .mes[is_user="true"] .avatar { right: 10px !important; }

#chat .mes::before {
  content: '' !important;
  display: block !important;
  margin: 8px 0 0 0 !important;
  height: 145px !important;
  width: 100% !important;
  background-image: url('') !important; /* 在此处自定义背景图*/
  background-repeat: no-repeat !important;
  background-position: center top !important;
  background-size: cover !important;
  border-radius: 2px !important;
  flex-shrink: 0 !important;
}

body #chat .mes::before {
  box-sizing: border-box !important;
  border: 1px solid rgba(0, 0, 0, 0.25) !important;
  border-radius: 2px !important;
  box-shadow: 0 0 0 2px white, inset 0 0 0 2px white, 0 0 10px rgba(0, 0, 0, 0.08) !important;
}

#chat .mes[is_user="false"] .ch_name,
#chat .mes[is_user="true"] .ch_name {
  position: static !important;
}

#chat .mes .ch_name .timestamp {
  position: absolute !important;
  bottom: 10px !important;
  z-index: 5 !important;
}

#chat .mes[is_user="false"] .timestamp { right: 6px !important; }
#chat .mes[is_user="true"] .timestamp { left: 6px !important; }

#chat .mes[is_user="false"] .mesAvatarWrapper { justify-content: flex-start; }
#chat .mes[is_user="true"] .mesAvatarWrapper { justify-content: flex-end !important; }

#chat .mes[is_user="false"] .ch_name {
  margin-left: 1px !important;
  text-align: left !important;
  margin-top: 32px !important;
}

#chat .mes[is_user="false"] .ch_name .name_text { text-align: left !important; }

#chat .mes[is_user="true"] .ch_name {
  margin-right: -1px !important;
  text-align: right !important;
  width: auto !important;
  max-width: none !important;
  white-space: nowrap !important;
  overflow: visible !important;
  direction: rtl;
  unicode-bidi: bidi-override;
  margin-top: 32px !important;
}

#chat .mes .ch_name .name_text {
  position: relative !important;
  z-index: 10 !important;
  font-size: 13px !important;
  font-weight: bold !important;
  margin-top: -10px !important;
  margin-bottom: 15px !important;
}

#chat .mes .avatar img {
  border: 3px solid white !important;
  box-shadow: 0 0 0 2px #f0f0f0 !important;
  border-radius: 50% !important;
}

#chat .mes .mes_buttons {
  position: absolute !important;
  filter: none !important;
  z-index: 10 !important;
}

#chat .mes[is_user="false"] .mes_buttons {
  top: 10px !important;
  right: 15px !important;
}

#chat .mes[is_user="true"] .mes_buttons {
  top: 10px !important;
  left: 15px !important;
}

#chat .mes[is_user="false"]::after {
  content: '' !important;
  position: absolute !important;
  left: -5px !important;
  top: 125px !important;
  width: 80px !important;
  height: 90px !important;
  background-image: none !important;
  background-color: white !important;
  border-radius: 2px !important;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.1), 0 2px 12px rgba(0, 0, 0, 0.02) !important;
  filter: none !important;
  z-index: 2 !important;
}

#chat .mes[is_user="true"]::after {
  content: '' !important;
  position: absolute !important;
  right: -5px !important;
  top: 125px !important;
  width: 80px !important;
  height: 90px !important;
  background-image: none !important;
  background-color: white !important;
  border-radius: 2px !important;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.1), 0 2px 12px rgba(0, 0, 0, 0.02) !important;
  filter: none !important;
  z-index: 2 !important;
}

/* 修复底栏布局偏移 @lambkinling */
body:not(.waifuMode) #sheld {
  top: var(--bottomFormBlockSize);
  height: calc(100dvh - var(--bottomFormBlockSize));
  min-height: calc(100dvh - var(--bottomFormBlockSize));
}

#send_form {
  border-radius: 0 !important;
  padding-top: 6px !important;
  padding-bottom: 6px !important;
  padding-left: 6px !important;
  padding-right: 6px !important;
  box-sizing: border-box !important;
  box-shadow: 0 -1px 2px rgba(0, 0, 0, 0.08) !important;
}

#send_textarea {
  clip-path: none !important;
  background-color: #f5f5f5 !important;
  border-radius: 4px !important;
  padding: 6px 4px !important;
  box-shadow: 0 1px 1px rgba(0, 0, 0, 0.1) !important;
  border-top: none !important;
}

/* 顶部导航栏图标 @blue_0310 */
#leftNavDrawerIcon,
#API-status-top,
#advanced-formatting-button .drawer-icon,
#WIDrawerIcon,
#user-settings-button .drawer-icon,
#logo_block .drawer-icon,
#backgrounds-drawer-toggle .drawer-icon,
#extensions-settings-button .drawer-icon,
#table_drawer_icon,
#persona-management-button .drawer-icon,
#rightNavDrawerIcon {
  opacity: 1 !important;
  transition: all 0.3s ease !important;
  font-size: 2em !important;
  transform: scale(0.85) !important;
  color: #b0b0b0 !important;
}

#extensionsMenuButton,
#send_but,
#options_button,
#mes_impersonate,
#mes_continue,
#mes_stop {
  opacity: 1 !important;
  transition: all 0.3s ease !important;
  font-size: 1.1em !important;
  transform: scale(0.85) !important;
  color: #b0b0b0 !important;
}

#extensionsMenuButton:hover,
#send_but:hover,
#options_button:hover {
  opacity: 1 !important;
  color: #d0d0d0 !important;
}

#top-bar { box-shadow: 0 1.8px 2px rgba(0, 0, 0, 0.08) !important; }

#nonQRFormItems { position: relative; }

#send_textarea::placeholder {
  color: transparent !important;
  text-shadow: none !important;
}

/* 自定义输入框占位文本 @inkfoxxxx */
#nonQRFormItems:has(#send_textarea:placeholder-shown)::before {
  content: "| 请输入文本..";
  color: #B9B9B9;
  position: absolute;
  top: 50%;
  left: 30%;
  transform: translate(-50%, -50%);
  font-style: normal;
  font-size: 0.5em;
  pointer-events: none;
  z-index: 10;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: calc(100% - 30px);
}

#chat .mes .mes_block { overflow: visible !important; }

#chat .mes[is_user="false"] .mes_block::before {
  content: '' !important;
  position: absolute !important;
  left: -55px !important;
  top: -55px !important;
  width: 75% !important;
  height: 40px !important;
  background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 140 40"><rect x="0" y="0" width="160" height="30" rx="8" fill="white"/><polygon points="40,30 45,40 50,30" fill="white"/></svg>') !important;
  background-size: 100% 100% !important;
  background-repeat: no-repeat !important;
  filter: drop-shadow(0 2px 1px rgba(0,0,0,0.08)) !important;
  z-index: 2 !important;
}

#chat .mes[is_user="true"] .mes_block::before {
  content: '' !important;
  position: absolute !important;
  right: -75px !important;
  top: -55px !important;
  width: 75% !important;
  height: 40px !important;
  background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 40"><rect x="0" y="0" width="100" height="30" rx="8" fill="white"/><polygon points="65,30 70,40 75,30" fill="white"/></svg>') !important;
  background-size: 100% 100% !important;
  background-repeat: no-repeat !important;
  filter: drop-shadow(0 2px 1px rgba(0,0,0,0.08)) !important;
  z-index: 2 !important;
}

#chat .mes[is_user="false"] .mes_block::after {
  content: '' !important;
  position: absolute !important;
  right: -5px !important;
  top: -30px !important;
  width: 80px !important;
  height: 30px !important;
  background-color: white !important;
  border-radius: 14px !important;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.1), 0 2px 12px rgba(0, 0, 0, 0.02) !important;
  background-image: url('data:image/svg+xml;base64,'),
    url('data:image/svg+xml;base64,') !important;
  background-size: 20px 20px, 20px 20px !important;
  background-position: 8px center, 44px center !important;
  background-repeat: no-repeat, no-repeat !important;
  z-index: 2 !important;
}

#chat .mes[is_user="true"] .mes_block::after {
  content: '' !important;
  position: absolute !important;
  left: -5px !important;
  top: -30px !important;
  width: 80px !important;
  height: 30px !important;
  background-color: white !important;
  border-radius: 14px !important;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.1), 0 2px 12px rgba(0, 0, 0, 0.02) !important;
  background-image: url('data:image/svg+xml;base64,'),
    url('data:image/svg+xml;base64,') !important;
  background-size: 20px 20px, 20px 20px !important;
  background-position: 8px center, 44px center !important;
  background-repeat: no-repeat, no-repeat !important;
  z-index: 2 !important;
}

#chat .mes .mesIDDisplay,
#chat .mes .tokenCounterDisplay,
#chat .mes .mes_timer {
  display: flex !important;
  visibility: visible !important;
  opacity: 0.8 !important;
  font-size: 10px !important;
  position: relative !important;
  z-index: 10 !important;
  margin: 4px 4px -3px 4px !important;
  align-self: flex-start !important;
}

#chat .mes[is_user="true"] .mesIDDisplay,
#chat .mes[is_user="true"] .tokenCounterDisplay {
  align-self: flex-end !important;
}

#chat .mes[is_user="true"] .mes_timer { display: none !important; }

#chat .mes .timestamp { position: relative !important; }

#chat .mes .timestamp::before {
  content: '' !important;
  display: block !important;
  width: 100% !important;
  height: 14px !important;
  margin-bottom: 2px !important;
  background-image: repeating-linear-gradient(
    90deg,
    #999 0px, #999 2px,
    #fff 2px, #fff 4px,
    #999 4px, #999 7px,
    #fff 7px, #fff 10px,
    #999 10px, #999 11px,
    #fff 11px, #fff 14px,
    #999 14px, #999 17px,
    #fff 17px, #fff 19px,
    #999 19px, #999 20px,
    #fff 20px, #fff 23px,
    #999 23px, #999 26px,
    #fff 26px, #fff 28px
  ) !important;
  border-radius: 1px !important;
}

#chat .mes .mes_reasoning_header {
    background-color: #ffffff !important;
    box-shadow: 0 0 4px rgba(0, 0, 0, 0.2) !important;
    outline: 1px solid #cccccc !important;
    outline-offset: -4px !important;
    border-radius: 6px !important;
    margin: 2px 10px !important;
}

#chat .mes .mes_reasoning_header .mes_reasoning_header_title::before {
    color: #888888 !important;
}

/* 思维链标题样式 @_nak.a.ri */
.mes_reasoning_header_title {
    font-size: 0;
}

.mes_reasoning_header_title::before {
    content: "正在思考中";
    font-size: 10px;
    color: #888888;
}

.mes_reasoning_arrow {
    display: none !important;
}

#chat .mes .mes_reasoning_header {
    background-color: #ffffff !important;
    box-shadow: 0 0 4px rgba(0, 0, 0, 0.2) !important;
    outline: 1px solid #cccccc !important;
    outline-offset: -4px !important;
    border-radius: 6px !important;
    margin: 2px 10px !important;
    display: flex !important;
    align-items: center !important;
    justify-content: space-between !important;
}

.mes_reasoning_header::before {
    content: '' !important;
    display: inline-block !important;
    width: 20px !important;
    height: 20px !important;
    background-image: url('data:image/svg+xml;base64,') !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    flex-shrink: 0 !important;
}

.mes_reasoning_header::after {
    content: '' !important;
    display: inline-block !important;
    width: 20px !important;
    height: 20px !important;
    background-image: url('data:image/svg+xml;base64,') !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    flex-shrink: 0 !important;
}

/* 思维链文本对齐 参考@lambkinling */
details.mes_reasoning_details .mes_reasoning {
  text-align: justify;
}

select {
    -webkit-appearance: none !important;
    -moz-appearance: none !important;
    appearance: none !important;
    background-image: none !important;
    background-color: #ffffff !important;
    transition: 0.1s ease-in-out !important;
    box-shadow: #FFFFFC 1.5px 1.5px 2px 0px inset, 2px 2px 4px rgba(0,0,0,0.08) !important;
    height: auto !important;
    padding: 2px 12px !important;
    border: none !important;
    border-radius: 8px !important;
    outline: none !important;
    line-height: 1.5 !important;
}

select:hover,
select:focus {
    background-color: #FFFFFC !important;
    box-shadow: #ffffff 1.5px 1.5px 2px 0px inset, 2px 2px 4px rgba(0,0,0,0.08) !important;
    animation: none !important;
    text-shadow: none !important;
}

select#themes,
select#chat_display {
    background-color: #FFFFFC !important;
    box-shadow: #ffffff 1.5px 1.5px 2px 0px inset, 2px 2px 4px rgba(0,0,0,0.08) !important;
}

select#themes:hover,
select#themes:focus,
select#chat_display:hover,
select#chat_display:focus {
    box-shadow: #ffffff 1.5px 1.5px 2px 0px inset, 2px 2px 4px rgba(0,0,0,0.08) !important;
}

#extensions_settings .inline-drawer-toggle.inline-drawer-header,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header,
#user-settings-block h4,
.standoutHeader {
    -webkit-appearance: none !important;
    -moz-appearance: none !important;
    appearance: none !important;
    background-image: none !important;
    background-color: #FFFAFB !important;
    transition: 0.1s ease-in-out !important;
    box-shadow: #ffffff 1.5px 1.5px 2px 0px inset, 2px 2px 4px rgba(0,0,0,0.1) !important;
    height: auto !important;
    padding: 2px 12px !important;
    border: none !important;
    border-radius: 6px !important;
    outline: none !important;
    line-height: 1.5 !important;
}

select#toastr_position {
    background-color: #FFFAFB !important;
    box-shadow: #ffffff 1.5px 1.5px 2px 0px inset, 2px 2px 4px rgba(0,0,0,0.1) !important;
}

select#toastr_position:hover,
select#toastr_position:focus {
    background-color: #FFFAFB !important;
    box-shadow: #ffffff 1.5px 1.5px 2px 0px inset, 2px 2px 4px rgba(0,0,0,0.1) !important;
}

input:not(input[type="range"], input[type="checkbox"]) {
    background-color: #FBFBFB !important;
    box-shadow: #ffffff 1.5px 1.5px 2px 0px inset, 2px 2px 4px rgba(0,0,0,0.08) !important;
    border: none !important;
    border-radius: 2px !important;
    outline: none !important;
    transition: 0.1s ease-in-out !important;
}

input:not(input[type="range"], input[type="checkbox"]):hover,
input:not(input[type="range"], input[type="checkbox"]):focus {
    background-color: #FFFFFC !important;
    box-shadow: #ffffff 1.5px 1.5px 2px 0px inset, 2px 2px 4px rgba(0,0,0,0.08) !important;
}

input[type="range"],
input[type="range"]:focus,
input[type="range"]:active {
    -webkit-appearance: none !important;
    appearance: none !important;
    width: 100% !important;
    margin: 0 0 2px 0 !important;
    border: none !important;
    background: transparent !important;
    outline: none !important;
    padding: 0;
    box-shadow: none !important;
}

input[type="range"]::-webkit-slider-runnable-track {
    width: 100%;
    height: 2px;
    background-color: #E8E8E8 !important;
    border: none;
    cursor: pointer;
    border-radius: 1px !important;
}

input[type="range"]::-webkit-slider-thumb {
    -webkit-appearance: none !important;
    appearance: none !important;
    width: 55px !important;
    height: 55px !important;
    /* 图源 @牛奶熊 */
    /* 可在此处替换为自定义滑块图片，格式：background-image: url('图片链接') !important; */
    background-image: url('https://files.catbox.moe/lq36up.png') !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    background-color: transparent !important;
    border: none !important;
    box-shadow: none !important;
    margin-top: -25px !important;
    cursor: pointer !important;
    transition: transform 0.2s ease !important;
}

input[type="range"]::-webkit-slider-thumb:hover {
    transform: scale(1.1) !important;
}

input[type="checkbox"] {
  appearance: none;
  -webkit-appearance: none;
  width: 12px;
  height: 12px;
  background-color: #fff;
  border: 2px solid rgba(245, 245, 245, 0);
  border-radius: 50%;
  position: relative;
  overflow: hidden;
  cursor: pointer;
  box-shadow: 0px 0px 0px 1px #F5F5F5;
}

input[type="checkbox"]::after {
  content: '';
  width: 40px;
  height: 40px;
  background-color: #F5F5F5;
  top: -35px;
  left: -35px;
  position: absolute;
  transform: rotateZ(45deg);
  pointer-events: none;
  transition: 700ms ease;
}

input[type="checkbox"]:checked::after {
  left: -7px;
  top: -7px;
}

